const API_KEY = 'FRED_key';

const series = [
  { series_id: 'VIXCLS', series_name: 'CBOE VIX', category: 'Volatility Complacency', score_direction: 'inverse', asset: 'Macro', asset_class: 'Volatility' },
  { series_id: 'BAMLH0A0HYM2', series_name: 'US High Yield Spread', category: 'Credit Excess', score_direction: 'inverse', asset: 'Credit', asset_class: 'Credit' },
  { series_id: 'BAMLC0A0CM', series_name: 'US Investment Grade Spread', category: 'Credit Excess', score_direction: 'inverse', asset: 'Credit', asset_class: 'Credit' },
  { series_id: 'BAMLC0A4CBBB', series_name: 'US BBB Spread', category: 'Credit Excess', score_direction: 'inverse', asset: 'Credit', asset_class: 'Credit' }
];

return series.map(s => ({
  json: {
    ...s,
    url: `https://api.stlouisfed.org/fred/series/observations?series_id=${s.series_id}&api_key=${API_KEY}&file_type=json&observation_start=2010-01-01`
  }
}));

function toNum(v){return (v==='.'||v==null||v==='')?null:Number(v)}
function pctRank(arr,val){const c=arr.filter(x=>Number.isFinite(x));if(!c.length)return null;return c.filter(x=>x<=val).length/c.length}
function regime(s){if(s>=85)return'Extreme';if(s>=70)return'High';if(s>=55)return'Elevated';if(s>=40)return'Normal';return'Low'}

const configItems=$items('Series Config (FRED)');
const httpItems=$input.all();
const out=[];

for(let i=0;i<httpItems.length;i++){
  const meta=configItems[i].json;
  const api=httpItems[i].json;
  const obs=api.observations||[];

  const cleaned=obs.map(o=>({date:o.date,value:toNum(o.value)})).filter(o=>o.value!=null&&Number.isFinite(o.value));
  if(!cleaned.length) continue;

  const latest=cleaned[cleaned.length-1];
  const values=cleaned.map(o=>o.value);
  const pct=pctRank(values,latest.value);
  const score=meta.score_direction==='inverse'?Math.round((1-pct)*100):Math.round(pct*100);

  out.push({json:{
    asset: meta.asset,
    asset_class: meta.asset_class,
    series_id: meta.series_id,
    series_name: meta.series_name,
    category: meta.category,
    latest_date: latest.date,
    latest_value: latest.value,
    percentile: Number(pct.toFixed(4)),
    score,
    regime: regime(score)
  }});
}
return out;

const data=$json.chart.result[0];
const ts=data.timestamp;
const px=data.indicators.quote[0].close;

const out=[];
for(let i=0;i<ts.length;i++){
  if(!px[i]) continue;
  const date=new Date(ts[i]*1000).toISOString().split('T')[0];
  out.push({json:{date,price:px[i]}});
}
return out;

const rows = $input.all();

if (rows.length < 21) {
  return [];
}

const latestIndex = rows.length - 1;
const prevIndex = latestIndex - 20;

const current = rows[latestIndex].json.price;
const prev = rows[prevIndex].json.price;

if (!current || !prev) {
  return [];
}

const momentum = (current / prev - 1) * 100;

const score = Math.min(100, Math.max(0, 50 + momentum));

const regime =
  score >= 85 ? "Extreme" :
  score >= 70 ? "High" :
  score >= 55 ? "Elevated" :
  score >= 40 ? "Normal" :
  "Low";

return [
  {
    json: {
      asset: "S&P 500",
      asset_class: "Equity",
      series_id: "SPX_MOM_1M",
      series_name: "S&P 500 1M Momentum",
      category: "Equity Momentum",
      latest_date: rows[latestIndex].json.date,
      latest_value: Number(momentum.toFixed(2)),
      percentile: null,
      score: Math.round(score),
      regime
    }
  }
];

const rows=$input.all().map(i=>i.json);

function avg(a){return Math.round(a.reduce((x,y)=>x+y,0)/a.length)}

const vol=rows.filter(r=>r.category==='Volatility Complacency');
const cred=rows.filter(r=>r.category==='Credit Excess');

const volScore=avg(vol.map(r=>r.score));
const credScore=avg(cred.map(r=>r.score));
const combined=avg([volScore,credScore]);

const run_date_sgt=new Date().toISOString().split('T')[0];

return [{json:{run_date_sgt,volScore,credScore,combined,rows}}];
